1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { registrarConfigured } from "./registrar";
7	
8	/* ------------------------------------------------------------------ *
9	 * Minimal name.com v4 client (Basic auth), mirroring lib/registrar.ts.
10	 * These endpoints aren't exposed by the shared registrar helper, so we
11	 * call them directly here. All calls are guarded by registrarConfigured().
12	 * ------------------------------------------------------------------ */
13	
14	function baseUrl(): string {
15	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
16	}
17	
18	function authHeader(): string {
19	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
20	  return "Basic " + Buffer.from(raw).toString("base64");
21	}
22	
23	async function nc(method: string, path: string, body?: unknown): Promise<any> {
24	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
25	  const res = await fetch(`${baseUrl()}${path}`, {
26	    method,
27	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
28	    body: body !== undefined ? JSON.stringify(body) : undefined,
29	    signal: AbortSignal.timeout(30_000),
30	  });
31	  const text = await res.text();
32	  let json: any = {};
33	  try {
34	    json = text ? JSON.parse(text) : {};
35	  } catch {
36	    /* non-JSON error body */
37	  }
38	  if (!res.ok) {
39	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
40	    throw new Error(`name.com: ${msg}`);
41	  }
42	  return json;
43	}
44	
45	function errMsg(e: unknown): string {
46	  return String(e instanceof Error ? e.message : e).slice(0, 200);
47	}
48	
49	const HOST_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;
50	
51	async function ownedDomain(domainId: string) {
52	  const user = await requireUser();
53	  const domain = await db.domain.findUnique({ where: { id: domainId } });
54	  if (!domain) throw new Error("Not found");
55	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
56	  return { user, domain };
57	}
58	
59	/* ------------------------------------------------------------------ *
60	 * Nameservers
61	 * ------------------------------------------------------------------ */
62	
63	export type NameserverResult = {
64	  error?: string;
65	  nameservers?: string[];
66	  registrarHit?: boolean;
67	  note?: string;
68	};
69	
70	/**
71	 * Persist custom nameservers on the Domain and, when the domain is ACTIVE
72	 * and the registrar is configured, push them to name.com. Two or more
73	 * valid hostnames are required for a registrar update; an empty list clears
74	 * the override locally (name.com default NS remain untouched).
75	 */
76	export async function updateNameservers(
77	  domainId: string,
78	  nameservers: string[]
79	): Promise<NameserverResult> {
80	  const { user, domain } = await ownedDomain(domainId);
81	
82	  const cleaned = (nameservers ?? [])
83	    .map((n) => n.trim().toLowerCase().replace(/\.$/, ""))
84	    .filter(Boolean);
85	  const unique = [...new Set(cleaned)];
86	
87	  for (const ns of unique) {
88	    if (!HOST_RE.test(ns)) return { error: `Invalid nameserver hostname: ${ns}` };
89	  }
90	  if (unique.length > 13) return { error: "At most 13 nameservers are allowed." };
91	  if (unique.length === 1) return { error: "Provide at least two nameservers." };
92	
93	  let registrarHit = false;
94	  let note: string | undefined;
95	
96	  if (unique.length >= 2) {
97	    if (domain.status === "ACTIVE" && registrarConfigured()) {
98	      try {
99	        await nc("POST", `/v4/domains/${encodeURIComponent(domain.name)}:setNameservers`, {
100	          nameservers: unique,
101	        });
102	        registrarHit = true;
103	      } catch (e) {
104	        return { error: `Registrar rejected the update: ${errMsg(e)}` };
105	      }
106	    } else {
107	      note =
108	        "Saved. These will be applied at the registrar once the domain is active and the registrar is configured.";
109	    }
110	  }
111	
112	  await db.domain.update({ where: { id: domainId }, data: { nameservers: unique } });
113	  await db.auditLog.create({
114	    data: {
115	      userId: user.id,
116	      action: "domain.nameservers",
117	      detail: `${domainId} -> [${unique.join(", ")}]${registrarHit ? " (registrar)" : ""}`,
118	    },
119	  });
120	  revalidatePath(`/dashboard/domains/${domainId}`);
121	  return { nameservers: unique, registrarHit, note };
122	}
123	
124	/* ------------------------------------------------------------------ *
125	 * WHOIS privacy
126	 * ------------------------------------------------------------------ */
127	
128	/**
129	 * Persist the WHOIS-privacy preference. name.com's privacy is a paid add-on
130	 * set at registration rather than a free live toggle, so this is persisted-
131	 * only: we record intent and surface a note. Ownership-checked.
132	 */
133	export async function setWhoisPrivacy(
134	  domainId: string,
135	  enabled: boolean
136	): Promise<{ error?: string; whoisPrivacy?: boolean; note?: string }> {
137	  const { user, domain } = await ownedDomain(domainId);
138	
139	  await db.domain.update({ where: { id: domainId }, data: { whoisPrivacy: enabled } });
140	  await db.auditLog.create({
141	    data: {
142	      userId: user.id,
143	      action: "domain.whois_privacy",
144	      detail: `${domainId} -> ${enabled ? "on" : "off"}`,
145	    },
146	  });
147	  revalidatePath(`/dashboard/domains/${domainId}`);
148	  return {
149	    whoisPrivacy: enabled,
150	    note: `Preference saved (${enabled ? "on" : "off"}). WHOIS privacy at ${domain.registrar} is provisioned at registration — contact support to change it on a live domain.`,
151	  };
152	}
