58	class DuplicateDomainError extends Error {
59	  constructor() {
60	    super("DUPLICATE_DOMAIN");
61	    this.name = "DuplicateDomainError";
62	  }
63	}
64	
65	const isUniqueConflict = (e: any) => e?.code === "P2002";
66	
67	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
68	
69	/**
70	 * After a registrar call fails or times out we must NOT assume the registration
71	 * did not happen — name.com may well have taken the order. Ask the registrar
72	 * before touching the customer's money:
73	 *  - the domain is in our reseller account  -> registered (keep the charge)
74	 *  - the domain is still purchasable        -> not registered (safe to refund)
75	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
76	 */
77	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
78	  try {
79	    const info = await domainInfo(domain);
80	    return { state: "registered", expires: info.expires };
81	  } catch {
82	    /* not in our account, or the API is unhappy — fall through to availability */
83	  }
84	  try {
85	    const [check] = await checkDomains([domain]);
86	    if (check?.available === true) return { state: "not-registered" };
87	  } catch {
88	    /* registrar unreachable */
89	  }
90	  return { state: "unknown" };
91	}
