418	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
419	  const domainId = String(formData.get("domainId") ?? "");
420	  let ctx;
421	  try {
422	    ctx = await ownedDomain(domainId);
423	  } catch (e: any) {
424	    return { error: e.message };
425	  }
426	  const parsed = z
427	    .object({
428	      name: z.string().max(120).default(""),
429	      type: z.enum(RECORD_TYPES),
430	      address: z.string().min(1).max(500),
431	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
432	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
433	    })
434	    .safeParse({
435	      name: formData.get("name") ?? "",
436	      type: formData.get("type"),
437	      address: formData.get("address"),
438	      ttl: formData.get("ttl") || 300,
439	      mxPref: formData.get("mxPref") || undefined,
440	    });
441	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
442	
443	  // "@" or blank => apex (name.com uses empty host for apex)
444	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
445	  try {
446	    await addRecord(ctx.domain.name, {
447	      host,
448	      type: parsed.data.type,
449	      answer: parsed.data.address,
450	      ttl: parsed.data.ttl,
451	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
452	    });
453	  } catch (e: any) {
454	    // Say what the provider said AND what to do about it. A bare registrar
455	    // string ("422 Unprocessable Entity") tells a customer nothing they can act
456	    // on; this product's standard is that an error explains both halves.
457	    return {
458	      error:
459	        `Your DNS provider refused this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
460	        `Check the value matches the record type (an A record needs an IPv4 address, a CNAME needs a hostname), ` +
461	        `then try again. Nothing was changed.`,
462	    };
463	  }
464	  revalidatePath(`/dashboard/domains/${domainId}`);
465	  return {};
466	}
