468	export async function deleteDnsRecord(
469	  domainId: string,
470	  record: { name: string; type: string; address: string }
471	): Promise<{ error?: string }> {
472	  let ctx;
473	  try {
474	    ctx = await ownedDomain(domainId);
475	  } catch (e: any) {
476	    return { error: e.message };
477	  }
478	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
479	  try {
480	    const recs = await listRecords(ctx.domain.name);
481	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
482	    if (!match) return { error: "Record not found (it may have already been removed). Refresh the page to see the current records." };
483	    await deleteRecord(ctx.domain.name, match.id);
484	  } catch (e: any) {
485	    return {
486	      error:
487	        `Your DNS provider refused to remove this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
488	        `The record is still in place — refresh the page and try again in a moment.`,
489	    };
490	  }
491	  revalidatePath(`/dashboard/domains/${domainId}`);
492	  return {};
