264	/**
265	 * Can this domain be transferred in, and what would it cost? Never throws for a
266	 * "no" answer — a non-transferable name comes back with `transferable: false`
267	 * and a reason the customer can act on.
268	 */
269	export async function checkTransfer(domain: string): Promise<TransferCheck> {
270	  if (SANDBOX) {
271	    // Synthetic: everything is transferable except names containing "locked",
272	    // which exercise the rejected-quote path in staging.
273	    const cost = sandboxTldCostCents(domain);
274	    if (domain.includes("locked")) {
275	      return {
276	        domain,
277	        transferable: false,
278	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
279	        premium: false,
280	        priceCents: null,
281	        costCents: null,
282	      };
283	    }
284	    return {
285	      domain,
286	      transferable: true,
287	      reason: null,
288	      premium: false,
289	      priceCents: retailCents(cost, await domainMarkupPct()),
290	      costCents: cost,
291	    };
292	  }
293	
294	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
295	  const r = (json.results ?? [])[0];
296	  if (!r) {
297	    return {
298	      domain,
299	      transferable: false,
300	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
301	      premium: false,
302	      priceCents: null,
303	      costCents: null,
304	    };
305	  }
306	  // Purchasable means nobody owns it — there is nothing to transfer.
307	  if (r.purchasable === true) {
308	    return {
309	      domain,
310	      transferable: false,
311	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
312	      premium: r.premium === true,
313	      priceCents: null,
314	      costCents: null,
315	    };
316	  }
317	  if (r.premium === true) {
318	    return {
319	      domain,
320	      transferable: false,
321	      reason: "Premium domains can't be transferred in automatically — contact support.",
322	      premium: true,
323	      priceCents: null,
324	      costCents: null,
325	    };
326	  }
327	
328	  const cost = await transferCostCents(domain, r);
329	  if (cost === null) {
330	    return {
331	      domain,
332	      transferable: false,
333	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
334	      premium: false,
335	      priceCents: null,
336	      costCents: null,
337	    };
338	  }
339	  return {
340	    domain,
341	    transferable: true,
342	    reason: null,
343	    premium: false,
344	    priceCents: retailCents(cost, await domainMarkupPct()),
345	    costCents: cost,
346	  };
347	}
