303	/* ------------------------------------------------------------------ *
304	 * URL forwarding / redirects (name.com URL-forwarding API).
305	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
306	 * Degrades to a persisted-intent Setting + note when unconfigured.
307	 * ------------------------------------------------------------------ */
308	
309	export type Redirect = { host: string; forwardsTo: string; type: string };
310	
311	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
312	
313	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
314	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
315	  if (!s?.value) return [];
316	  try {
317	    const parsed = JSON.parse(s.value);
318	    return Array.isArray(parsed) ? parsed : [];
319	  } catch {
320	    return [];
321	  }
322	}
323	
324	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
325	  await db.setting.upsert({
326	    where: { key: redirectStoreKey(domainId) },
327	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
328	    update: { value: JSON.stringify(list) },
329	  });
330	}
331	
332	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
333	
334	/** List forwardings — live from name.com when possible, else persisted intent. */
335	export async function listRedirects(domainId: string): Promise<RedirectsView> {
336	  let ctx;
337	  try {
338	    ctx = await ownedDomain(domainId);
339	  } catch (e) {
340	    return { forwards: [], live: false, error: errMsg(e) };
341	  }
342	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
343	    try {
344	      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`);
345	      const forwards: Redirect[] = (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
346	        host: f.host ?? "",
347	        forwardsTo: f.forwardsTo ?? "",
348	        type: f.type ?? "redirect301",
349	      }));
350	      return { forwards, live: true };
351	    } catch (e) {
352	      // Fall back to intent store but tell the truth about why.
353	      const forwards = await readRedirectIntent(domainId);
354	      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
355	    }
356	  }
357	  const forwards = await readRedirectIntent(domainId);
358	  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
359	}
360	
361	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
362	
363	export async function setRedirect(
364	  domainId: string,
365	  hostRaw: string,
366	  forwardsTo: string,
367	  type: string
368	): Promise<RedirectsView> {
369	  let ctx;
370	  try {
371	    ctx = await ownedDomain(domainId);
372	  } catch (e) {
373	    return { forwards: [], live: false, error: errMsg(e) };
374	  }
375	  const host = normHost(hostRaw);
